382	  function matchScopedApiRoute(route: PluginApiRouteDeclaration, method: string, requestPath: string) {
383	    if (route.method !== method) return null;
384	    const normalize = (value: string) => value.replace(/\/+$/, "") || "/";
385	    const routeSegments = normalize(route.path).split("/").filter(Boolean);
386	    const requestSegments = normalize(requestPath).split("/").filter(Boolean);
387	    if (routeSegments.length !== requestSegments.length) return null;
388	    const params: Record<string, string> = {};
389	    for (let i = 0; i < routeSegments.length; i += 1) {
390	      const routeSegment = routeSegments[i]!;
391	      const requestSegment = requestSegments[i]!;
392	      if (routeSegment.startsWith(":")) {
393	        params[routeSegment.slice(1)] = decodeURIComponent(requestSegment);
394	        continue;
395	      }
396	      if (routeSegment !== requestSegment) return null;
397	    }
398	    return params;
399	  }
