401	  function sanitizePluginRequestHeaders(req: Request): Record<string, string> {
402	    const safeHeaderNames = new Set([
403	      "accept",
404	      "content-type",
405	      "user-agent",
406	      "x-paperclip-run-id",
407	      "x-request-id",
408	    ]);
409	    const headers: Record<string, string> = {};
410	    for (const [name, value] of Object.entries(req.headers)) {
411	      const lower = name.toLowerCase();
412	      if (!safeHeaderNames.has(lower)) continue;
413	      if (Array.isArray(value)) {
414	        headers[lower] = value.join(", ");
415	      } else if (typeof value === "string") {
416	        headers[lower] = value;
417	      }
418	    }
419	    return headers;
420	  }
