422	  function applyPluginScopedApiResponseHeaders(
423	    res: Response,
424	    headers: Record<string, string> | undefined,
425	  ): void {
426	    for (const [name, value] of Object.entries(headers ?? {})) {
427	      const lower = name.toLowerCase();
428	      if (!PLUGIN_SCOPED_API_RESPONSE_HEADER_ALLOWLIST.has(lower)) continue;
429	      res.setHeader(lower, value);
430	    }
431	  }
