433	  function normalizeQuery(query: Request["query"]): Record<string, string | string[]> {
434	    const normalized: Record<string, string | string[]> = {};
435	    for (const [key, value] of Object.entries(query)) {
436	      if (typeof value === "string") {
437	        normalized[key] = value;
438	      } else if (Array.isArray(value)) {
439	        normalized[key] = value.map((entry) => String(entry));
440	      }
441	    }
442	    return normalized;
443	  }
