445	  async function resolveScopedApiCompanyId(
446	    route: PluginApiRouteDeclaration,
447	    params: Record<string, string>,
448	    req: Request,
449	  ) {
450	    const resolution = route.companyResolution;
451	    if (!resolution) {
452	      if (req.actor.type === "agent" && req.actor.companyId) return req.actor.companyId;
453	      return null;
454	    }
455	
456	    if (resolution.from === "body") {
457	      const body = req.body as Record<string, unknown> | undefined;
458	      const companyId = body?.[resolution.key ?? ""];
459	      return typeof companyId === "string" ? companyId : null;
460	    }
461	
462	    if (resolution.from === "query") {
463	      const value = req.query[resolution.key ?? ""];
464	      return typeof value === "string" ? value : null;
465	    }
466	
467	    const issueId = params[resolution.param ?? ""];
468	    if (!issueId) return null;
469	    const issue = await issuesSvc.getById(issueId);
470	    return issue?.companyId ?? null;
471	  }
