473	  function assertScopedApiAuth(req: Request, route: PluginApiRouteDeclaration) {
474	    if (route.auth === "board") {
475	      assertBoard(req);
476	      return;
477	    }
478	    if (route.auth === "agent") {
479	      assertAuthenticated(req);
480	      if (req.actor.type !== "agent") throw forbidden("Agent access required");
481	      return;
482	    }
483	    if (route.auth === "webhook") {
484	      throw unprocessable("Webhook-scoped plugin API routes require a signature verifier and are not enabled");
485	    }
486	    assertAuthenticated(req);
487	    if (req.actor.type !== "board" && req.actor.type !== "agent") {
488	      throw forbidden("Board or agent access required");
489	    }
490	  }
