492	  async function enforceScopedApiCheckout(
493	    req: Request,
494	    route: PluginApiRouteDeclaration,
495	    params: Record<string, string>,
496	    companyId: string,
497	  ) {
498	    const policy = route.checkoutPolicy ?? "none";
499	    if (policy === "none" || req.actor.type !== "agent") return;
500	    const issueId = params.issueId;
501	    if (!issueId) {
502	      throw unprocessable("Checkout-protected plugin API routes require an issueId route parameter");
503	    }
504	    const issue = await issuesSvc.getById(issueId);
505	    if (!issue || issue.companyId !== companyId) {
506	      throw notFound("Issue not found");
507	    }
508	    if (policy === "required-for-agent-in-progress") {
509	      if (issue.status !== "in_progress" || issue.assigneeAgentId !== req.actor.agentId) return;
510	    }
511	    const runId = req.actor.runId?.trim();
512	    if (!runId) {
513	      throw unauthorized("Agent run id required");
514	    }
515	    if (!req.actor.agentId) {
516	      throw forbidden("Agent authentication required");
517	    }
518	    await issuesSvc.assertCheckoutOwner(issueId, req.actor.agentId, runId);
519	  }
